<?php
namespace App\Services;
class Midtrans {public static function snap(array $order,array $customer):array{$key=(string)(\Env::MIDTRANS_SERVER_KEY??'');if($key==='')throw new \RuntimeException('Midtrans is not configured');$base=(\Env::MIDTRANS_IS_PRODUCTION??false)?'https://app.midtrans.com':'https://app.sandbox.midtrans.com';$payload=['transaction_details'=>['order_id'=>$order['order_number'],'gross_amount'=>(int)$order['total']],'customer_details'=>['first_name'=>$customer['full_name'],'email'=>$customer['email']]];$c=curl_init($base.'/snap/v1/transactions');curl_setopt_array($c,[CURLOPT_RETURNTRANSFER=>true,CURLOPT_POST=>true,CURLOPT_POSTFIELDS=>json_encode($payload),CURLOPT_TIMEOUT=>20,CURLOPT_HTTPHEADER=>['Authorization: Basic '.base64_encode($key.':'),'Content-Type: application/json']]);$raw=curl_exec($c);$code=(int)curl_getinfo($c,CURLINFO_HTTP_CODE);curl_close($c);$data=json_decode((string)$raw,true);if($code<200||$code>=300||empty($data['token']))throw new \RuntimeException('Failed to create Midtrans payment');return $data;}}
